CHAPTER_META = {'chapter_num': 5, 'title': 'Measurement of Length and Motion', 'subject': 'Science', 'grade': 'Class 6', 'book': 'Curiosity (NEP 2020)', 'total_slides': 20, 'concept_slides': 16, 'quiz_slides': 4, 'checkpoints_count': 32, 'quiz_questions_count': 40}

SLIDES = [{'id': 1, 'title': 'Why Measure', 'subtitle': "Deepa's Story: Traditional Body Units vs Precise Measuring Tapes", 'concept_html': '\n<div class="grid grid-cols-1 md:grid-cols-2 gap-4">\n    <div class="bg-slate-800/80 p-4 rounded-xl border border-indigo-500/30 shadow-lg">\n        <h4 class="text-indigo-400 font-bold text-base mb-2 flex items-center gap-2">\n            <span>✂️</span> Deepa at the Tailor Shop\n        </h4>\n        <p class="text-slate-300 text-sm leading-relaxed mb-3">\n            Deepa visits a tailor shop to get a new school uniform stitched. Her mother estimates the cloth length using <strong>char angula</strong> (four-finger width) and handspans.\n        </p>\n        <p class="text-slate-300 text-sm leading-relaxed">\n            The tailor, however, uses a calibrated, flexible <strong>measuring tape</strong>. He takes exact measurements of Deepa\'s shoulder width, sleeve length, and height to cut fabric with flawless precision.\n        </p>\n    </div>\n    <div class="bg-slate-800/80 p-4 rounded-xl border border-amber-500/30 shadow-lg">\n        <h4 class="text-amber-400 font-bold text-base mb-2 flex items-center gap-2">\n            <span>🗣️</span> The Friends\' Classroom Inquiry\n        </h4>\n        <ul class="text-slate-300 text-sm space-y-2">\n            <li class="flex items-start gap-2">\n                <span class="text-amber-400 font-bold">•</span>\n                <span><strong>Anish & Hardeep:</strong> Wonder why carpenters use steel tapes instead of pacing with feet.</span>\n            </li>\n            <li class="flex items-start gap-2">\n                <span class="text-amber-400 font-bold">•</span>\n                <span><strong>Padma & Tasneem:</strong> Notice that flowers sold in garlands are measured by the cubit (forearm length).</span>\n            </li>\n            <li class="flex items-start gap-2">\n                <span class="text-amber-400 font-bold">•</span>\n                <span><strong>Core Question:</strong> Can human body parts provide reliable measurements for everyone?</span>\n            </li>\n        </ul>\n    </div>\n</div>\n<div class="mt-4 p-3 bg-indigo-950/40 rounded-xl border border-indigo-500/20 text-xs text-indigo-300">\n    <strong>Key Takeaway:</strong> Body measurements are intuitive and accessible anywhere, but modern engineering, commerce, and scientific research demand reliable standard units that do not change from person to person.\n</div>\n', 'lecture_script': 'Welcome to our exploration of measurement and motion! Think about a simple morning routine: buying vegetables by weight, walking 500 metres to school, or stitching a school uniform. When Deepa visited the tailor with her mother, her mother estimated fabric length using traditional handspans and char angula, meaning four-finger widths. But the tailor took out a marked, flexible measuring tape. Why could the tailor not simply rely on his own fingers or handspan? When Deepa discussed this with her friends Anish, Hardeep, Padma, and Tasneem, they realized that measurement touches every single aspect of human life. From building houses and sewing clothes to navigating satellites into space, humanity needs to know: how long, how tall, how fast, and how far. In this chapter, we discover how humankind transitioned from arbitrary body parts to universal scientific standards.', 'spoken_text': "Slide 1: Why Measure. Deepa's Story: Traditional Body Units vs Precise Measuring Tapes. Welcome to our exploration of measurement and motion! Think about a simple morning routine: buying vegetables by weight, walking 500 metres to school, or stitching a school uniform. When Deepa visited the tailor with her mother, her mother estimated fabric length using traditional handspans and char angula, meaning four-finger widths. But the tailor took out a marked, flexible measuring tape. Why could the tailor not simply rely on his own fingers or handspan? When Deepa discussed this with her friends Anish, Hardeep, Padma, and Tasneem, they realized that measurement touches every single aspect of human life. From building houses and sewing clothes to navigating satellites into space, humanity needs to know: how long, how tall, how fast, and how far. In this chapter, we discover how humankind transitioned from arbitrary body parts to universal scientific standards.", 'checkpoints': [{'question': 'Why did the tailor use a calibrated measuring tape instead of handspans?', 'options': ['Handspans are illegal', 'Measuring tape provides standard, precise, and repeatable measurements', 'Cloth cannot be touched by hands', 'Tape makes the cloth longer'], 'correct': 1, 'explanation': 'A calibrated measuring tape has fixed standard markings that give identical readings regardless of who measures.', 'study_insight': 'Handspans vary widely depending on age, height, and bone structure.'}, {'question': 'What traditional body measurement refers to the width of four fingers?', 'options': ['Balisht', 'Char Angula', 'Dhanusa', 'Yojana'], 'correct': 1, 'explanation': 'Char angula is a traditional Indian measurement representing the collective width of four fingers.', 'study_insight': 'Ancient artisans used angula as a quick proportional check during woodworking and sculpture.'}]}, {'id': 2, 'title': 'Shifting Spans', 'subtitle': 'Activity 5.1: Handspans, Cubits, Footsteps & The Definition of a Unit', 'concept_html': '\n<div class="grid grid-cols-1 md:grid-cols-2 gap-4">\n    <div class="bg-slate-800/80 p-4 rounded-xl border border-sky-500/30">\n        <h4 class="text-sky-400 font-bold text-base mb-2">Activity 5.1: Measuring the Table</h4>\n        <p class="text-slate-300 text-sm leading-relaxed mb-3">\n            Ask five different students to measure the exact same teacher\'s desk using their <strong>handspan (balisht)</strong>—the span from thumb tip to little finger tip when fully outstretched.\n        </p>\n        <div class="bg-sky-950/40 p-3 rounded-lg border border-sky-500/20 text-xs text-sky-300 space-y-1.5">\n            <div><strong>Recorded Student Data:</strong></div>\n            <div>• Student A (Tall): <strong>11 handspans</strong></div>\n            <div>• Student B (Medium): <strong>13 handspans</strong></div>\n            <div>• Student C (Short): <strong>15 handspans</strong></div>\n            <div class="text-amber-300 font-bold">Conclusion: The table\'s physical length did not change, but the reported number changed because handspan size is not uniform!</div>\n        </div>\n    </div>\n    <div class="bg-slate-800/80 p-4 rounded-xl border border-indigo-500/30">\n        <h4 class="text-indigo-400 font-bold text-base mb-2">The Scientific Anatomy of Measurement</h4>\n        <p class="text-slate-300 text-sm leading-relaxed mb-3">\n            Every scientific measurement consists of exactly <strong>two essential parts</strong>:\n        </p>\n        <div class="p-3 bg-slate-900 rounded-lg border border-slate-700 space-y-2 text-xs text-slate-300">\n            <div>\n                <strong class="text-emerald-400">1. A Numerical Magnitude (Number):</strong> Tells us how many times the reference unit fits into the measured quantity (e.g., <strong>12</strong>).\n            </div>\n            <div>\n                <strong class="text-indigo-400">2. A Chosen Unit (Standard Reference):</strong> A known, fixed quantity of the same kind chosen for comparison (e.g., <strong>handspan</strong> or <strong>metre</strong>).\n            </div>\n            <div class="pt-1 text-slate-400">\n                Formula: <code>Measurement = Number x Unit</code> (e.g., <code>12 metres</code>).\n            </div>\n        </div>\n    </div>\n</div>\n', 'lecture_script': 'In ancient times, humans did not possess factory-made plastic rulers or laser tape measures. So what did they do? They used their own bodies! A handspan, known as balisht in Hindi, was the distance from the tip of the outstretched thumb to the tip of the little finger. A cubit, or hath, was the distance from the elbow to the tip of the middle finger. And footsteps, or paces, were used to measure outdoor farm boundaries. But here is the fundamental problem demonstrated in Activity 5.1: if three students measure the same classroom table, one records 11 handspans, another records 13, and a younger child records 15! The table itself never grew or shrank. The variation happened because every human hand is anatomically unique. A measurement always has two parts: a number and a unit. If the unit changes with every person, trade and science collapse into chaos. That is why standard units are essential.', 'spoken_text': 'Slide 2: Body Units and Inconsistency. Activity 5.1: Handspans, Cubits, Footsteps and The Definition of a Unit. In ancient times, humans did not possess factory-made plastic rulers or laser tape measures. So what did they do? They used their own bodies! A handspan, known as balisht in Hindi, was the distance from the tip of the outstretched thumb to the tip of the little finger. A cubit, or hath, was the distance from the elbow to the tip of the middle finger. And footsteps, or paces, were used to measure outdoor farm boundaries. But here is the fundamental problem demonstrated in Activity 5.1: if three students measure the same classroom table, one records 11 handspans, another records 13, and a younger child records 15! The table itself never grew or shrank. The variation happened because every human hand is anatomically unique. A measurement always has two parts: a number and a unit. If the unit changes with every person, trade and science collapse into chaos. That is why standard units are essential.', 'checkpoints': [{'question': 'What are the two essential components of any physical measurement?', 'options': ['Colour and shape', 'A number and a unit', 'Weight and volume', 'Speed and direction'], 'correct': 1, 'explanation': 'Every measurement requires a numerical value (magnitude) and a standard reference quantity called a unit (e.g., 5 metres).', 'study_insight': "Writing just '5' is meaningless without specifying the unit of measure."}, {'question': 'Why did different students get different handspan counts for the same table in Activity 5.1?', 'options': ['The table kept shrinking', 'Different people have different handspan sizes', 'The classroom was too dark', 'Rulers were bent'], 'correct': 1, 'explanation': 'Human hand dimensions vary from person to person, making handspans an inconsistent, non-standard unit.', 'study_insight': 'Non-standard units lead to commercial disputes and scientific error.'}]}, {'id': 3, 'title': 'Ancient Scales', 'subtitle': "From Lothal's Ivory Scale to Angula, Dhanusa & Yojana", 'concept_html': '\n<div class="grid grid-cols-1 md:grid-cols-2 gap-4">\n    <div class="bg-slate-800/80 p-4 rounded-xl border border-amber-500/30">\n        <h4 class="text-amber-400 font-bold text-base mb-2 flex items-center gap-2">\n            <span>🏛️</span> Harappan Precision Engineering\n        </h4>\n        <p class="text-slate-300 text-sm leading-relaxed mb-3">\n            Excavations at the ancient Indus Valley port city of <strong>Lothal (Gujarat)</strong> unearthed an intricately calibrated <strong>ivory measuring scale</strong> dating back over 4,400 years (c. 2400 BCE).\n        </p>\n        <p class="text-slate-300 text-sm leading-relaxed">\n            The markings on this scale were spaced just <strong>1.7 millimetres</strong> apart! This proves Harappan town planners and dock engineers used standardized metric-like precision to build parallel streets and modular kiln-fired brick docks.\n        </p>\n    </div>\n    <div class="bg-slate-800/80 p-4 rounded-xl border border-emerald-500/30">\n        <h4 class="text-emerald-400 font-bold text-base mb-2 flex items-center gap-2">\n            <span>📜</span> Ancient Indian Length Hierarchy\n        </h4>\n        <div class="space-y-2 text-xs text-slate-300">\n            <div class="p-2 bg-slate-900 rounded border border-slate-700">\n                <strong class="text-emerald-300">1. Angula (Finger Width):</strong> The foundational base unit for carpentry, medical surgery tools (Sushruta Samhita), and temple iconography.\n            </div>\n            <div class="p-2 bg-slate-900 rounded border border-slate-700">\n                <strong class="text-emerald-300">2. Dhanusa (Bow Length):</strong> Equivalent to 4 hastas (approx. 1.8 metres), used for land surveying and fortress architecture.\n            </div>\n            <div class="p-2 bg-slate-900 rounded border border-slate-700">\n                <strong class="text-emerald-300">3. Yojana:</strong> Classical cosmic and long-distance travel unit mentioned in ancient astronomy, roughly equal to 12 to 15 kilometres.\n            </div>\n        </div>\n    </div>\n</div>\n', 'lecture_script': "India possesses one of the world's most glorious and sophisticated histories of standardized measurement. Long before European civilizations adopted unified scales, the Harappan civilization of the Indus Valley engineered breathtaking planned cities like Mohenjo-daro, Harappa, and Lothal in Gujarat. Archaeologists at Lothal unearthed a polished ivory ruler with finely incised linear graduations spaced approximately 1.7 millimetres apart! That is smaller than one-sixteenth of an inch, representing the smallest division ever recorded in Bronze Age archaeology. Furthermore, classical Indian literature systematized units into an elegant mathematical hierarchy: from the angula, which was defined as the average width of a finger, up through the hasta (cubit), the dhanusa (bow length for land surveying), all the way to the yojana for interstate travel and astronomical distances.", 'spoken_text': "Slide 3: Ancient Scales. From Lothal's Ivory Scale to Angula, Dhanusa and Yojana. India possesses one of the world's most glorious and sophisticated histories of standardized measurement. Long before European civilizations adopted unified scales, the Harappan civilization of the Indus Valley engineered breathtaking planned cities like Mohenjo-daro, Harappa, and Lothal in Gujarat. Archaeologists at Lothal unearthed a polished ivory ruler with finely incised linear graduations spaced approximately 1.7 millimetres apart! That is smaller than one-sixteenth of an inch, representing the smallest division ever recorded in Bronze Age archaeology. Furthermore, classical Indian literature systematized units into an elegant mathematical hierarchy: from the angula, which was defined as the average width of a finger, up through the hasta (cubit), the dhanusa (bow length for land surveying), all the way to the yojana for interstate travel and astronomical distances.", 'checkpoints': [{'question': 'What ancient Indus Valley archaeological site revealed a precisely calibrated ivory measuring scale?', 'options': ['Lothal', 'Sarnath', 'Hampi', 'Kanchipuram'], 'correct': 0, 'explanation': 'An ivory scale with precision divisions of approximately 1.7 mm was discovered at Lothal in Gujarat.', 'study_insight': 'Harappan bricks followed strict standardized dimension ratios across thousands of miles.'}, {'question': 'Which ancient Indian unit was used to measure long intercity travel distances?', 'options': ['Angula', 'Balisht', 'Yojana', 'Char Angula'], 'correct': 2, 'explanation': 'Yojana was an ancient Indian unit for long terrestrial distances, roughly equivalent to 12 to 15 kilometres.', 'study_insight': 'Angula was small (finger-width), while yojana spanned entire kingdoms.'}]}, {'id': 4, 'title': 'The Metre', 'subtitle': 'The International System of Units & The Standard Metre', 'concept_html': '\n<div class="grid grid-cols-1 md:grid-cols-2 gap-4">\n    <div class="bg-slate-800/80 p-4 rounded-xl border border-cyan-500/30">\n        <h4 class="text-cyan-400 font-bold text-base mb-2">The Need for Global Standardisation</h4>\n        <p class="text-slate-300 text-sm leading-relaxed mb-3">\n            In the 18th century, almost every country, province, and port city used different units for length (such as cubits, varas, leagues, and inches).\n        </p>\n        <p class="text-slate-300 text-sm leading-relaxed">\n            This caused severe confusion in international trade, shipping, and scientific collaboration. To create global uniformity, scientists established the <strong>International System of Units</strong> (abbreviated as <strong>SI</strong> from the French <em>Système International d\'Unités</em>) in 1960.\n        </p>\n    </div>\n    <div class="bg-slate-800/80 p-4 rounded-xl border border-indigo-500/30">\n        <h4 class="text-indigo-400 font-bold text-base mb-2">The Metre: Base SI Unit of Length</h4>\n        <div class="p-3 bg-indigo-950/40 rounded-lg border border-indigo-500/20 text-xs text-indigo-300 space-y-2">\n            <div>\n                <strong>Symbol:</strong> Lowercase <code>m</code> (never capitalized <code>M</code>).\n            </div>\n            <div>\n                <strong>Definition:</strong> The standard base unit of length in the SI system is the <strong>metre</strong>.\n            </div>\n            <div>\n                <strong>Global Standard Bar:</strong> Originally preserved as a platinum-iridium bar in Paris, now defined with laser precision by the speed of light in vacuum.\n            </div>\n        </div>\n    </div>\n</div>\n', 'lecture_script': 'Imagine buying three yards of silk in London, only to find it equals a different length in Cairo, Paris, or Tokyo! By the late eighteenth century, international trade was paralyzed by hundreds of competing regional systems. A merchant could not reliably order screws, cloth, or machinery parts from another nation. To solve this once and for all, scientists worldwide convened and adopted the International System of Units, widely known as the SI system. For length, they established one single, universally respected base unit: the metre. Today, whether you are a scientist in New Delhi, a pilot in London, an astronaut aboard the International Space Station, or an engineer in Tokyo, one metre means the exact same physical length everywhere on Earth and beyond.', 'spoken_text': 'Slide 4: The Metre. The International System of Units and The Standard Metre. Imagine buying three yards of silk in London, only to find it equals a different length in Cairo, Paris, or Tokyo! By the late eighteenth century, international trade was paralyzed by hundreds of competing regional systems. A merchant could not reliably order screws, cloth, or machinery parts from another nation. To solve this once and for all, scientists worldwide convened and adopted the International System of Units, widely known as the SI system. For length, they established one single, universally respected base unit: the metre. Today, whether you are a scientist in New Delhi, a pilot in London, an astronaut aboard the International Space Station, or an engineer in Tokyo, one metre means the exact same physical length everywhere on Earth and beyond.', 'checkpoints': [{'question': 'What is the standard base SI unit of length across the globe?', 'options': ['Foot', 'Metre', 'Inch', 'Yard'], 'correct': 1, 'explanation': 'The metre (m) is the internationally accepted SI base unit for measuring length.', 'study_insight': "SI stands for Système International d'Unités."}, {'question': 'What is the correct scientific symbol for the metre?', 'options': ['M', 'mt', 'm', 'mtr'], 'correct': 2, 'explanation': "The SI symbol for the metre is strictly a lowercase 'm'.", 'study_insight': "Uppercase 'M' stands for mega (million), so '10 M' is completely wrong for metres."}]}, {'id': 5, 'title': 'Metric Powers', 'subtitle': 'Converting Kilometres, Metres, Centimetres & Millimetres', 'concept_html': '\n<div class="grid grid-cols-1 md:grid-cols-3 gap-3">\n    <div class="bg-slate-800/80 p-3 rounded-xl border border-emerald-500/30">\n        <div class="text-emerald-400 font-bold text-sm mb-1">1. Millimetre (mm)</div>\n        <p class="text-xs text-slate-300 mb-1">Tiny subunit for pencil lead thickness, wire gauges, and insect wings.</p>\n        <div class="font-mono text-xs text-emerald-300 font-bold">1 cm = 10 mm</div>\n        <div class="font-mono text-[11px] text-slate-400">1 mm = 0.1 cm = 0.001 m</div>\n    </div>\n    <div class="bg-slate-800/80 p-3 rounded-xl border border-sky-500/30">\n        <div class="text-sky-400 font-bold text-sm mb-1">2. Centimetre (cm)</div>\n        <p class="text-xs text-slate-300 mb-1">Subunit for measuring notebooks, pens, shoes, and textbook pages.</p>\n        <div class="font-mono text-xs text-sky-300 font-bold">1 m = 100 cm</div>\n        <div class="font-mono text-[11px] text-slate-400">1 cm = 0.01 m</div>\n    </div>\n    <div class="bg-slate-800/80 p-3 rounded-xl border border-amber-500/30">\n        <div class="text-amber-400 font-bold text-sm mb-1">3. Kilometre (km)</div>\n        <p class="text-xs text-slate-300 mb-1">Large multiple for road trips, railway tracks, and intercity distances.</p>\n        <div class="font-mono text-xs text-amber-300 font-bold">1 km = 1000 m</div>\n        <div class="font-mono text-[11px] text-slate-400">1 km = 100,000 cm</div>\n    </div>\n</div>\n<div class="mt-3 p-3 bg-slate-900 rounded-xl border border-slate-700 text-xs text-slate-300 flex justify-between items-center">\n    <span><strong>Customary Unit Equivalents:</strong> 1 inch = 2.54 cm • 1 foot = 12 inches = 30.48 cm • 1 yard = 3 feet ≈ 0.914 m</span>\n</div>\n', 'lecture_script': "While the metre is our standard base unit, the universe contains objects of wildly different dimensions. You cannot measure the thickness of a mosquito's leg in metres, nor would you measure the distance from Delhi to Mumbai in millimetres! The metric system is brilliantly structured using powers of ten. For small objects, we divide one metre into 100 equal parts called centimetres. Each centimetre is further subdivided into 10 equal parts called millimetres. Look at your 15-centimetre school ruler: the tiniest little lines are spaced exactly one millimetre apart. For vast geographical distances, such as highways connecting cities, we group 1,000 metres together into one kilometre. Converting between these units is simple arithmetic: multiply or divide by 10, 100, or 1,000.", 'spoken_text': "Slide 5: Multiples and Subunits. Converting Kilometres, Metres, Centimetres and Millimetres. While the metre is our standard base unit, the universe contains objects of wildly different dimensions. You cannot measure the thickness of a mosquito's leg in metres, nor would you measure the distance from Delhi to Mumbai in millimetres! The metric system is brilliantly structured using powers of ten. For small objects, we divide one metre into 100 equal parts called centimetres. Each centimetre is further subdivided into 10 equal parts called millimetres. Look at your 15-centimetre school ruler: the tiniest little lines are spaced exactly one millimetre apart. For vast geographical distances, such as highways connecting cities, we group 1,000 metres together into one kilometre. Converting between these units is simple arithmetic: multiply or divide by 10, 100, or 1,000.", 'checkpoints': [{'question': 'How many millimetres are there in 1 centimetre?', 'options': ['10 mm', '100 mm', '1,000 mm', '0.1 mm'], 'correct': 0, 'explanation': '1 centimetre is divided into exactly 10 equal millimetres.', 'study_insight': 'The smallest division marked on a typical school ruler is 1 mm.'}, {'question': 'How many metres make up 1 kilometre?', 'options': ['100 m', '500 m', '1,000 m', '10,000 m'], 'correct': 2, 'explanation': "The prefix 'kilo' means one thousand, so 1 kilometre = 1,000 metres.", 'study_insight': '1 km equals 100,000 centimetres.'}]}, {'id': 6, 'title': 'Tool Choice', 'subtitle': "15-cm Rulers, Metre Rods, Flexible Tailor's Tapes & Surveyor Chains", 'concept_html': '\n<div class="grid grid-cols-1 md:grid-cols-2 gap-4">\n    <div class="bg-slate-800/80 p-4 rounded-xl border border-teal-500/30">\n        <h4 class="text-teal-400 font-bold text-base mb-2">Matching the Tool to the Object</h4>\n        <ul class="text-xs text-slate-300 space-y-2">\n            <li class="flex items-start gap-2">\n                <span class="text-teal-400 font-bold">•</span>\n                <span><strong>15-cm or 30-cm Plastic Scale:</strong> Ideal for flat, straight, handheld items (geometry figures, pencils, eraser length).</span>\n            </li>\n            <li class="flex items-start gap-2">\n                <span class="text-teal-400 font-bold">•</span>\n                <span><strong>Rigid Wooden / Steel Metre Rod:</strong> Used by cloth merchants on counters to unroll and measure fabric reams.</span>\n            </li>\n            <li class="flex items-start gap-2">\n                <span class="text-teal-400 font-bold">•</span>\n                <span><strong>Flexible Tailor\'s Tape:</strong> Made of fiberglass or flexible vinyl to wrap around curved surfaces (chest girth, waist, tree trunk circumference).</span>\n            </li>\n            <li class="flex items-start gap-2">\n                <span class="text-teal-400 font-bold">•</span>\n                <span><strong>Long Steel Measuring Tape:</strong> 30-metre or 50-metre coiled tape for room dimensions, sports running tracks, and building architecture.</span>\n            </li>\n        </ul>\n    </div>\n    <div class="bg-slate-800/80 p-4 rounded-xl border border-rose-500/30">\n        <h4 class="text-rose-400 font-bold text-base mb-2">Why a Straight Scale Fails on Curves</h4>\n        <p class="text-slate-300 text-sm leading-relaxed mb-3">\n            If you try to measure the girth of a round banyan tree trunk with a stiff wooden ruler, the ruler cannot bend without snapping.\n        </p>\n        <p class="text-slate-300 text-sm leading-relaxed">\n            Only a <strong>flexible measuring tape</strong> or a <strong>thread</strong> can conform closely to curved geometry without leaving gaps.\n        </p>\n    </div>\n</div>\n', 'lecture_script': "A good scientist always selects the appropriate tool for the job. You would never use an axe to sharpen a pencil, nor would you use a rigid 15-centimetre plastic ruler to measure the girth of a round tree trunk! If an object is straight, flat, and small, such as a notebook or pencil, a 15-centimetre scale is perfect. If you visit a textile merchant, you will see them using a rigid one-metre steel rod to quickly measure running lengths of cotton fabric. But if you are measuring your own waist, chest girth, or the perimeter of a curved football, a stiff ruler is completely useless. For curved surfaces, tailor's tapes made of flexible fiberglass ribbon hug the contours effortlessly. And for large school sports grounds or building foundations, construction workers use long 30-metre coiled steel surveyor tapes.", 'spoken_text': "Slide 6: Tool Choice. 15-cm Rulers, Metre Rods, Flexible Tailor's Tapes and Surveyor Chains. A good scientist always selects the appropriate tool for the job. You would never use an axe to sharpen a pencil, nor would you use a rigid 15-centimetre plastic ruler to measure the girth of a round tree trunk! If an object is straight, flat, and small, such as a notebook or pencil, a 15-centimetre scale is perfect. If you visit a textile merchant, you will see them using a rigid one-metre steel rod to quickly measure running lengths of cotton fabric. But if you are measuring your own waist, chest girth, or the perimeter of a curved football, a stiff ruler is completely useless. For curved surfaces, tailor's tapes made of flexible fiberglass ribbon hug the contours effortlessly. And for large school sports grounds or building foundations, construction workers use long 30-metre coiled steel surveyor tapes.", 'checkpoints': [{'question': 'Which measuring device is most suitable for measuring the circumference of a round tree trunk?', 'options': ['A stiff 15-cm plastic ruler', "A flexible tailor's measuring tape", 'A heavy wooden beam', 'A compass needle'], 'correct': 1, 'explanation': "A flexible tailor's tape curves smoothly around cylindrical objects like tree trunks or body girth.", 'study_insight': 'Rigid rulers cannot bend around curved boundaries.'}, {'question': 'What tool does a cloth merchant use on the counter to measure straight fabric lengths?', 'options': ['A 1-metre rigid metal rod', 'A sewing needle', 'Handspans', 'A pair of scissors'], 'correct': 0, 'explanation': 'Cloth merchants use a calibrated 1-metre rigid metal rod to rapidly measure flat unrolled cloth.', 'study_insight': 'The rigid rod prevents fabric stretching or wrinkling during measurement.'}]}, {'id': 7, 'title': 'Eye Angle', 'subtitle': "Position of the Eye: Direct Vertical Alignment (Position 'B')", 'concept_html': '\n<div class="grid grid-cols-1 md:grid-cols-2 gap-4">\n    <div class="bg-slate-800/80 p-4 rounded-xl border border-amber-500/30">\n        <h4 class="text-amber-400 font-bold text-base mb-2">What is Parallax Error?</h4>\n        <p class="text-slate-300 text-sm leading-relaxed mb-3">\n            <strong>Parallax error</strong> is the apparent shift in an object\'s position against a scale background caused by viewing it from an oblique or tilted angle.\n        </p>\n        <p class="text-slate-300 text-sm leading-relaxed">\n            Because a standard ruler has thickness, looking at a mark from the left or right creates an angular line of sight that falls on the wrong division!\n        </p>\n    </div>\n    <div class="bg-slate-800/80 p-4 rounded-xl border border-emerald-500/30">\n        <h4 class="text-emerald-400 font-bold text-base mb-2">The Three Viewing Positions</h4>\n        <div class="space-y-2 text-xs text-slate-300">\n            <div class="p-2 bg-rose-950/40 rounded border border-rose-500/20">\n                <strong class="text-rose-300">Position \'A\' (Viewed from Left):</strong> Angular skew makes the object appear slightly <em>longer</em> than it truly is (Positive Error).\n            </div>\n            <div class="p-2 bg-emerald-950/40 rounded border border-emerald-500/30">\n                <strong class="text-emerald-300">Position \'B\' (Directly Above at 90°):</strong> The eye is positioned vertically right above the reading point. <strong>Zero parallax error! True scientific reading.</strong>\n            </div>\n            <div class="p-2 bg-rose-950/40 rounded border border-rose-500/20">\n                <strong class="text-rose-300">Position \'C\' (Viewed from Right):</strong> Angular skew makes the object appear slightly <em>shorter</em> than it truly is (Negative Error).\n            </div>\n        </div>\n    </div>\n</div>\n', 'lecture_script': "Have you ever noticed that if you look at a car's speedometer from the passenger seat, the needle seems to show a slightly different speed than what the driver sees? That optical illusion is called parallax! In laboratory measurements, parallax error is one of the most common mistakes students make. When you place a ruler next to a pencil, the ruler has a small thickness of about two millimetres. If your eye is positioned off to the left at Position A, your sight line crosses the tick mark at an angle, giving an artificially high reading. If your eye is off to the right at Position C, the reading is artificially low. The only scientifically accurate technique is Position B: your line of sight must be exactly perpendicular, forming a 90-degree vertical angle directly over the graduation mark.", 'spoken_text': "Slide 7: Eye Angle. Position of the Eye: Direct Vertical Alignment Position B. Have you ever noticed that if you look at a car's speedometer from the passenger seat, the needle seems to show a slightly different speed than what the driver sees? That optical illusion is called parallax! In laboratory measurements, parallax error is one of the most common mistakes students make. When you place a ruler next to a pencil, the ruler has a small thickness of about two millimetres. If your eye is positioned off to the left at Position A, your sight line crosses the tick mark at an angle, giving an artificially high reading. If your eye is off to the right at Position C, the reading is artificially low. The only scientifically accurate technique is Position B: your line of sight must be exactly perpendicular, forming a 90-degree vertical angle directly over the graduation mark.", 'checkpoints': [{'question': 'Which eye position eliminates parallax error when reading a ruler?', 'options': ['Slanted from the left (Position A)', 'Directly vertically above the mark (Position B)', 'Slanted from the right (Position C)', 'Looking from underneath the table'], 'correct': 1, 'explanation': 'Position B places the line of sight vertically at 90 degrees directly above the mark, eliminating parallax.', 'study_insight': 'Viewing from side angles A or C leads to parallax reading errors.'}, {'question': 'What is parallax error caused by?', 'options': ['A broken ruler', 'Incorrect angular line of sight due to looking from the side', 'The temperature of the room', 'Using a metric scale'], 'correct': 1, 'explanation': 'Parallax error arises when the eye is not positioned vertically perpendicular to the scale division.', 'study_insight': 'Always align your eye directly over the scale mark being recorded.'}]}, {'id': 8, 'title': 'Broken Zeros', 'subtitle': 'Damaged Ends, Non-Zero Starting Marks & Offset Subtraction', 'concept_html': '\n<div class="grid grid-cols-1 md:grid-cols-2 gap-4">\n    <div class="bg-slate-800/80 p-4 rounded-xl border border-indigo-500/30">\n        <h4 class="text-indigo-400 font-bold text-base mb-2">The Common Problem: Broken Zero Edge</h4>\n        <p class="text-slate-300 text-sm leading-relaxed mb-3">\n            In school classrooms, the plastic zero edge of rulers frequently chips off, wears down, or snaps, making the 0.0 cm mark illegible.\n        </p>\n        <p class="text-slate-300 text-sm leading-relaxed">\n            Does a broken zero mark mean the entire ruler must be thrown in the trash? <strong>No!</strong> You can still measure with 100% precision using the offset subtraction method.\n        </p>\n    </div>\n    <div class="bg-slate-800/80 p-4 rounded-xl border border-emerald-500/30">\n        <h4 class="text-emerald-400 font-bold text-base mb-2">The Offset Subtraction Rule</h4>\n        <div class="p-3 bg-emerald-950/40 rounded-lg border border-emerald-500/20 text-xs text-emerald-300 space-y-2">\n            <div>\n                <strong>Step 1:</strong> Align the starting end of the object with any clear, intact whole number mark (such as <strong>1.0 cm</strong> or <strong>2.0 cm</strong>).\n            </div>\n            <div>\n                <strong>Step 2:</strong> Read the mark at the opposite end of the object (say <strong>7.4 cm</strong>).\n            </div>\n            <div>\n                <strong>Step 3:</strong> Calculate true length by subtracting initial mark from final mark:\n            </div>\n            <div class="p-2 bg-slate-900 rounded font-mono text-center font-bold text-amber-300">\n                True Length = Final Reading - Initial Reading<br>\n                Length = 7.4 cm - 1.0 cm = 6.4 cm\n            </div>\n        </div>\n    </div>\n</div>\n', 'lecture_script': 'Have you ever dropped your plastic pencil box and chipped the corner of your ruler right where the zero mark sits? Many students panic and think the ruler is now ruined and useless. But a true scientist knows that any point on a scale can serve as a starting line! If the zero mark is chipped or blurry, do not start at the broken edge. Instead, place the start of your pencil cleanly at the 1.0 centimetre mark, or even the 2.0 centimetre mark. Now look at where the tip of the pencil ends. If the tip aligns with 7.4 centimetres, what is the length of the pencil? It is not 7.4! You must subtract the starting offset: 7.4 centimetres minus 1.0 centimetre gives exactly 6.4 centimetres. By subtracting the initial reading from the final reading, you obtain perfectly accurate measurements every time.', 'spoken_text': 'Slide 8: Broken Zeros. Damaged Ends, Non-Zero Starting Marks and Offset Subtraction. Have you ever dropped your plastic pencil box and chipped the corner of your ruler right where the zero mark sits? Many students panic and think the ruler is now ruined and useless. But a true scientist knows that any point on a scale can serve as a starting line! If the zero mark is chipped or blurry, do not start at the broken edge. Instead, place the start of your pencil cleanly at the 1.0 centimetre mark, or even the 2.0 centimetre mark. Now look at where the tip of the pencil ends. If the tip aligns with 7.4 centimetres, what is the length of the pencil? It is not 7.4! You must subtract the starting offset: 7.4 centimetres minus 1.0 centimetre gives exactly 6.4 centimetres. By subtracting the initial reading from the final reading, you obtain perfectly accurate measurements every time.', 'checkpoints': [{'question': 'A student measures an eraser starting at 2.0 cm on a broken scale. The other end aligns with 5.5 cm. What is the true length of the eraser?', 'options': ['5.5 cm', '3.5 cm', '7.5 cm', '2.0 cm'], 'correct': 1, 'explanation': 'True Length = Final Reading - Initial Reading = 5.5 cm - 2.0 cm = 3.5 cm.', 'study_insight': 'Always subtract the starting mark when measuring from a non-zero mark.'}, {'question': 'What should you do if the zero mark of a ruler is worn out or broken?', 'options': ['Throw the ruler away immediately', 'Start measuring from any clear full mark (like 1.0 cm) and subtract that value', 'Guess the length by sight', 'Add 10 cm to whatever you see'], 'correct': 1, 'explanation': 'Aligning with an intact mark like 1.0 cm and subtracting the initial offset preserves total measurement accuracy.', 'study_insight': 'Offsets cancel out cleanly using simple subtraction.'}]}, {'id': 9, 'title': 'Symbol Rules', 'subtitle': 'Formatting Conventions, Symbol Grammar & Inclusive Tactile Scales', 'concept_html': '\n<div class="grid grid-cols-1 md:grid-cols-2 gap-4">\n    <div class="bg-slate-800/80 p-4 rounded-xl border border-sky-500/30">\n        <h4 class="text-sky-400 font-bold text-base mb-2">Scientific Writing Conventions</h4>\n        <ul class="text-xs text-slate-300 space-y-2">\n            <li class="flex items-start gap-2">\n                <span class="text-emerald-400 font-bold">✓</span>\n                <span><strong>Insert a Space:</strong> Always put a single space between the number and unit: <code>15 cm</code>, never <code>15cm</code>.</span>\n            </li>\n            <li class="flex items-start gap-2">\n                <span class="text-emerald-400 font-bold">✓</span>\n                <span><strong>No Plural \'s\' on Symbols:</strong> Symbols never take an \'s\'. Write <code>10 cm</code>, never <code>10 cms</code>; <code>5 m</code>, never <code>5 ms</code> (since \'ms\' means milliseconds!).</span>\n            </li>\n            <li class="flex items-start gap-2">\n                <span class="text-emerald-400 font-bold">✓</span>\n                <span><strong>Lowercase Unit Symbols:</strong> Write <code>m</code>, <code>cm</code>, <code>mm</code>, <code>km</code> in lowercase.</span>\n            </li>\n            <li class="flex items-start gap-2">\n                <span class="text-emerald-400 font-bold">✓</span>\n                <span><strong>No Trailing Periods:</strong> Do not put a full stop after a unit symbol unless it falls at the very end of a sentence.</span>\n            </li>\n        </ul>\n    </div>\n    <div class="bg-slate-800/80 p-4 rounded-xl border border-purple-500/30">\n        <h4 class="text-purple-400 font-bold text-base mb-2 flex items-center gap-2">\n            <span>🦯</span> Inclusive Accessibility: Tactile Scales\n        </h4>\n        <p class="text-slate-300 text-sm leading-relaxed mb-3">\n            How do visually challenged students measure lengths in science class?\n        </p>\n        <p class="text-slate-300 text-sm leading-relaxed">\n            Specialized <strong>tactile rulers</strong> are manufactured with raised, embossed dots and notched edges. Students glide their fingertips along the embossed ridges to read centimetre and millimetre increments independently by touch.\n        </p>\n    </div>\n</div>\n', 'lecture_script': "Science is a universal international language, and just like grammar in English, the SI system has strict writing rules. If you write your units incorrectly, it can completely alter the scientific meaning! First, always leave a space between the number and the unit symbol—write fifteen space centimetres, never cramming them together. Second, symbols are mathematical shorthand and never take a plural 's'. If you write ten followed by c-m-s, that is wrong. In fact, if you write five followed by m-s thinking it means five metres, a physicist will read it as five milliseconds! Third, unit symbols like metre, centimetre, and kilometre must be written in lowercase. Furthermore, modern science education is inclusive: visually challenged students use beautifully designed tactile rulers with raised embossed dots so that everyone can participate in precision measurement.", 'spoken_text': "Slide 9: Symbol Rules. Formatting Conventions, Symbol Grammar and Inclusive Tactile Scales. Science is a universal international language, and just like grammar in English, the SI system has strict writing rules. If you write your units incorrectly, it can completely alter the scientific meaning! First, always leave a space between the number and the unit symbol—write fifteen space centimetres, never cramming them together. Second, symbols are mathematical shorthand and never take a plural 's'. If you write ten followed by c-m-s, that is wrong. In fact, if you write five followed by m-s thinking it means five metres, a physicist will read it as five milliseconds! Third, unit symbols like metre, centimetre, and kilometre must be written in lowercase. Furthermore, modern science education is inclusive: visually challenged students use beautifully designed tactile rulers with raised embossed dots so that everyone can participate in precision measurement.", 'checkpoints': [{'question': 'Which of the following is written according to proper SI scientific conventions?', 'options': ['15cms.', '15 cm', '15CM', '15cm.'], 'correct': 1, 'explanation': "'15 cm' correctly has a space between number and unit, uses lowercase 'cm', and does not include a plural 's' or trailing full stop.", 'study_insight': "Never add an 's' to unit symbols; 'ms' means milliseconds, not metres."}, {'question': 'How do visually challenged students measure length accurately?', 'options': ['By estimating with their footsteps', 'Using tactile rulers with raised embossed markings that can be felt by touch', 'By asking someone else to measure for them', 'They cannot measure length'], 'correct': 1, 'explanation': 'Tactile rulers feature embossed notches and Braille-like dots enabling independent reading by touch.', 'study_insight': 'Assistive tactile technology promotes inclusive laboratory learning.'}]}, {'id': 10, 'title': 'Curved Paths', 'subtitle': 'Activity 5.4: Winding Rivers, Thread Mapping & Scale Straightening', 'concept_html': '\n<div class="grid grid-cols-1 md:grid-cols-2 gap-4">\n    <div class="bg-slate-800/80 p-4 rounded-xl border border-teal-500/30">\n        <h4 class="text-teal-400 font-bold text-base mb-2">The Curved Line Dilemma</h4>\n        <p class="text-slate-300 text-sm leading-relaxed mb-3">\n            Consider measuring the length of a curved verandah arch, a winding river route drawn on a map, or the perimeter of an oval leaf.\n        </p>\n        <p class="text-slate-300 text-sm leading-relaxed">\n            A straight rigid scale cannot bend along winding contours. Attempting to place a rigid scale across chords cuts across corners, drastically underestimating true path length.\n        </p>\n    </div>\n    <div class="bg-slate-800/80 p-4 rounded-xl border border-amber-500/30">\n        <h4 class="text-amber-400 font-bold text-base mb-2">The Flexible Thread Technique</h4>\n        <div class="p-3 bg-amber-950/40 rounded-lg border border-amber-500/20 text-xs text-amber-300 space-y-2">\n            <div>\n                <strong>Step 1:</strong> Tie a tiny knot at one end of a flexible piece of cotton thread to mark the origin point <code>A</code>.\n            </div>\n            <div>\n                <strong>Step 2:</strong> Press the knot at the start of the curve. Using your thumb and forefinger, carefully guide small segments of the thread along the exact curved contour.\n            </div>\n            <div>\n                <strong>Step 3:</strong> Mark the point where the thread reaches the curve\'s end <code>B</code> with ink.\n            </div>\n            <div>\n                <strong>Step 4:</strong> Pull the thread straight and place it alongside a standard metre rule to read the exact length!\n            </div>\n        </div>\n    </div>\n</div>\n', 'lecture_script': 'Nature rarely moves in perfectly straight lines. Think about a serpentine river meandering through a valley, a curved road winding up a mountain hill station, or decorative string fairy lights draped over an arched doorway. How can you measure the length of a curved line when your ruler is completely straight and stiff? The answer is an ingenious method using a simple piece of flexible thread! In Activity 5.4, we tie a small knot at one end of a thread and place it at point A on the curve. Holding the thread down with your thumb, you trace it along small segments of the curved path, keeping the thread snug against the contour. When you reach the end point B, mark the thread with a pen. Finally, stretch the thread taut and straight against a standard metre scale. Instantly, the curved length is revealed with precision!', 'spoken_text': 'Slide 10: Curved Paths. Activity 5.4: Winding Rivers, Thread Mapping and Scale Straightening. Nature rarely moves in perfectly straight lines. Think about a serpentine river meandering through a valley, a curved road winding up a mountain hill station, or decorative string fairy lights draped over an arched doorway. How can you measure the length of a curved line when your ruler is completely straight and stiff? The answer is an ingenious method using a simple piece of flexible thread! In Activity 5.4, we tie a small knot at one end of a thread and place it at point A on the curve. Holding the thread down with your thumb, you trace it along small segments of the curved path, keeping the thread snug against the contour. When you reach the end point B, mark the thread with a pen. Finally, stretch the thread taut and straight against a standard metre scale. Instantly, the curved length is revealed with precision!', 'checkpoints': [{'question': 'How can the length of a curved line drawn on paper be measured accurately?', 'options': ['By bending a rigid wooden scale until it breaks', 'Using a flexible thread along the curve and then measuring the straightened thread on a ruler', 'By guessing based on colour', 'Using an ordinary kitchen thermometer'], 'correct': 1, 'explanation': 'A thread conforms to the curve; once straightened out against a ruler, it yields the true curve length.', 'study_insight': 'This technique is also used by cartographers to measure winding rivers on geographical maps.'}, {'question': 'Why does measuring a curved path with small straight ruler chords give an incorrect result?', 'options': ['It cuts across corners and underestimates the true curved distance', 'Straight rulers absorb ink', 'It makes the line disappear', 'Chords are longer than curves'], 'correct': 0, 'explanation': 'Straight chords skip the outer curvature of the curve, yielding a value shorter than the actual winding path.', 'study_insight': 'The curved contour is always longer than the direct chord line connecting points.'}]}, {'id': 11, 'title': 'The Origin', 'subtitle': 'Describing Position, Coordinate Origins & Highway Milestones', 'concept_html': '\n<div class="grid grid-cols-1 md:grid-cols-2 gap-4">\n    <div class="bg-slate-800/80 p-4 rounded-xl border border-blue-500/30">\n        <h4 class="text-blue-400 font-bold text-base mb-2">What is a Reference Point?</h4>\n        <p class="text-slate-300 text-sm leading-relaxed mb-3">\n            To state where an object is located, you must always specify its position with respect to a fixed known landmark called the <strong>reference point</strong> (or <strong>origin</strong>).\n        </p>\n        <p class="text-slate-300 text-sm leading-relaxed">\n            If you say, <em>"The school is 2 kilometres away,"</em> that statement is incomplete! Is it 2 km from your home? From the railway station? Or from the bus depot?\n        </p>\n    </div>\n    <div class="bg-slate-800/80 p-4 rounded-xl border border-amber-500/30">\n        <h4 class="text-amber-400 font-bold text-base mb-2">Roadside Highway Milestones</h4>\n        <p class="text-slate-300 text-sm leading-relaxed mb-3">\n            When driving along national highways in India, yellow and white stone markers indicate numbers like <strong>DELHI 120 km</strong>.\n        </p>\n        <div class="p-3 bg-amber-950/40 rounded-lg border border-amber-500/20 text-xs text-amber-300">\n            <strong>Reference Interpretation:</strong> Here, the city center of Delhi serves as the fixed <strong>reference point</strong>. The milestone tells drivers their current position is 120 km away from that reference origin along that highway.\n        </div>\n    </div>\n</div>\n', 'lecture_script': "Imagine calling a friend and saying: 'I am standing two kilometres away!' Your friend will immediately ask: 'Two kilometres from where?' Without a fixed reference point, describing position or location is utterly impossible! In physics, a reference point is a known, stationary location from which distance and direction are measured. If Deepa says her school is two kilometres north of the central railway station, the railway station is the reference point. If she describes it from her grandmother's house, the distance and direction change completely. When you travel on a national highway and see a milestone marked 'Agra 85', Agra is the reference point, telling you that your current location is eighty-five kilometres from the Agra reference post.", 'spoken_text': "Slide 11: The Origin. Describing Position, Coordinate Origins and Highway Milestones. Imagine calling a friend and saying: I am standing two kilometres away! Your friend will immediately ask: Two kilometres from where? Without a fixed reference point, describing position or location is utterly impossible! In physics, a reference point is a known, stationary location from which distance and direction are measured. If Deepa says her school is two kilometres north of the central railway station, the railway station is the reference point. If she describes it from her grandmother's house, the distance and direction change completely. When you travel on a national highway and see a milestone marked Agra 85, Agra is the reference point, telling you that your current location is eighty-five kilometres from the Agra reference post.", 'checkpoints': [{'question': 'What is a fixed point used to describe the position and distance of an object called?', 'options': ['Reference point (origin)', 'Moving point', 'Focal point of light', 'Linear unit'], 'correct': 0, 'explanation': 'A reference point is a stationary landmark relative to which position, distance, and direction are determined.', 'study_insight': 'All spatial coordinates require a specified reference origin.'}, {'question': "A roadside milestone displays 'JAIPUR 45 km'. What is the reference point in this context?", 'options': ['The car', 'The city of Jaipur', 'The Sun', "The driver's home"], 'correct': 1, 'explanation': 'Jaipur is the reference point from which the remaining 45 km distance is measured.', 'study_insight': 'Highway milestones use target cities as their standard reference points.'}]}, {'id': 12, 'title': 'Rest & Motion', 'subtitle': 'Change in Position Over Time Relative to a Reference Point', 'concept_html': '\n<div class="grid grid-cols-1 md:grid-cols-2 gap-4">\n    <div class="bg-slate-800/80 p-4 rounded-xl border border-emerald-500/30">\n        <h4 class="text-emerald-400 font-bold text-base mb-2 flex items-center gap-2">\n            <span>🛑</span> State of Rest\n        </h4>\n        <p class="text-slate-300 text-sm leading-relaxed mb-3">\n            An object is said to be at <strong>rest</strong> if its position does not change with respect to its surroundings (reference point) as time passes.\n        </p>\n        <div class="p-2.5 bg-emerald-950/40 rounded-lg border border-emerald-500/20 text-xs text-emerald-300">\n            <strong>Examples:</strong> A blackboard mounted on a classroom wall, a tree rooted in soil, or a textbook resting on a table.\n        </div>\n    </div>\n    <div class="bg-slate-800/80 p-4 rounded-xl border border-sky-500/30">\n        <h4 class="text-sky-400 font-bold text-base mb-2 flex items-center gap-2">\n            <span>🏃</span> State of Motion\n        </h4>\n        <p class="text-slate-300 text-sm leading-relaxed mb-3">\n            An object is said to be in <strong>motion</strong> if its position continuously changes with respect to a reference point as time passes.\n        </p>\n        <div class="p-2.5 bg-sky-950/40 rounded-lg border border-sky-500/20 text-xs text-sky-300">\n            <strong>Examples:</strong> A flying bird flapping across the sky, a football rolling across turf, or a train pulling away from a station platform.\n        </div>\n    </div>\n</div>\n', 'lecture_script': "Look around your room right now. What objects are stationary, and what objects are moving? In science, we define rest and motion with strict precision based on time and position. If an object does not change its position relative to a chosen reference point as seconds and minutes tick by, that object is at rest. The blackboard mounted on your classroom wall, the heavy desk, and the trees outside the window are all at rest relative to the school building. But if an object's position changes over time, it is in a state of motion. A bird flying past the window, a car cruising down the street, or the moving second-hand on a wall clock are all in motion. Notice the key words: change in position over time with respect to a reference point.", 'spoken_text': "Slide 12: Rest and Motion Defined. Change in Position Over Time Relative to a Reference Point. Look around your room right now. What objects are stationary, and what objects are moving? In science, we define rest and motion with strict precision based on time and position. If an object does not change its position relative to a chosen reference point as seconds and minutes tick by, that object is at rest. The blackboard mounted on your classroom wall, the heavy desk, and the trees outside the window are all at rest relative to the school building. But if an object's position changes over time, it is in a state of motion. A bird flying past the window, a car cruising down the street, or the moving second-hand on a wall clock are all in motion. Notice the key words: change in position over time with respect to a reference point.", 'checkpoints': [{'question': 'When is an object scientifically said to be in motion?', 'options': ['When it makes a loud sound', 'When its position changes relative to a reference point over time', 'When it gets warmer', 'When it changes colour'], 'correct': 1, 'explanation': "Motion is defined strictly as a change in an object's spatial position over time relative to a chosen reference frame.", 'study_insight': 'Without a change in position over time, an object is at rest.'}, {'question': 'Which of the following is an example of an object at rest relative to the classroom?', 'options': ['A student walking to the door', 'A blackboard fixed firmly to the wall', 'A butterfly flying in the room', 'A rolling chalk piece'], 'correct': 1, 'explanation': 'The fixed blackboard does not change its position relative to the classroom walls over time.', 'study_insight': 'Stationary objects maintain constant relative distance and direction.'}]}, {'id': 13, 'title': 'Relative Move', 'subtitle': 'The Moving Bus Paradox: Simultaneous Rest & Motion', 'concept_html': '\n<div class="grid grid-cols-1 md:grid-cols-2 gap-4">\n    <div class="bg-slate-800/80 p-4 rounded-xl border border-purple-500/30">\n        <h4 class="text-purple-400 font-bold text-base mb-2">The Moving Bus Thought Experiment</h4>\n        <p class="text-slate-300 text-sm leading-relaxed mb-3">\n            Imagine you and your friend are sitting peacefully side-by-side inside a school bus cruising down the highway at <strong>60 km/h</strong>.\n        </p>\n        <div class="p-3 bg-purple-950/40 rounded-lg border border-purple-500/20 text-xs text-purple-300 space-y-1.5">\n            <div><strong>Are you in motion, or are you at rest?</strong></div>\n            <div>• Relative to your friend sitting next to you: <strong>At Rest!</strong> Your distance and direction from your friend do not change.</div>\n            <div>• Relative to a person standing by the roadside: <strong>In Rapid Motion!</strong> You are speeding past at 60 km/h along with the bus.</div>\n        </div>\n    </div>\n    <div class="bg-slate-800/80 p-4 rounded-xl border border-amber-500/30">\n        <h4 class="text-amber-400 font-bold text-base mb-2">Motion Depends on the Observer!</h4>\n        <p class="text-slate-300 text-sm leading-relaxed mb-3">\n            There is no such thing as \'absolute rest\' in our universe!\n        </p>\n        <p class="text-slate-300 text-sm leading-relaxed">\n            Even while you sleep motionless in bed, you and your house are hurtling through space at over <strong>100,000 km/h</strong> as planet Earth orbits around the Sun! <strong>Rest and motion are always relative.</strong>\n        </p>\n    </div>\n</div>\n', 'lecture_script': 'Here is one of the most mind-bending truths in all of science: an object can be at rest and in motion at the exact same moment! How is that possible? Consider sitting on a passenger train or school bus moving smoothly down the road. Look at the passenger sitting in the seat next to you. Are they moving? To you, they are sitting perfectly still; their position relative to your seat is not changing at all. You both appear at rest. But now look out the window at a person standing on the roadside. To that outside observer, both you and your friend are whizzing past at sixty kilometres per hour! An object at rest from one point of view is in rapid motion from another point of view. Motion is never absolute—it is always relative to the chosen reference frame.', 'spoken_text': 'Slide 13: Relative Move. The Moving Bus Paradox: Simultaneous Rest and Motion. Here is one of the most mind-bending truths in all of science: an object can be at rest and in motion at the exact same moment! How is that possible? Consider sitting on a passenger train or school bus moving smoothly down the road. Look at the passenger sitting in the seat next to you. Are they moving? To you, they are sitting perfectly still; their position relative to your seat is not changing at all. You both appear at rest. But now look out the window at a person standing on the roadside. To that outside observer, both you and your friend are whizzing past at sixty kilometres per hour! An object at rest from one point of view is in rapid motion from another point of view. Motion is never absolute—it is always relative to the chosen reference frame.', 'checkpoints': [{'question': 'A passenger sitting inside a moving bus is at rest with respect to which of the following?', 'options': ['A tree outside by the road', 'A fellow passenger sitting in the next seat', 'A pedestrian on the footpath', 'A car driving past the bus'], 'correct': 1, 'explanation': 'Relative to a fellow passenger inside the bus, their position remains unchanged over time, so they are at rest.', 'study_insight': 'Motion is relative to the chosen reference frame.'}, {'question': "Does any object in the universe experience 'absolute rest'?", 'options': ['Yes, mountains on Earth', 'No, rest and motion are always relative to a chosen reference frame', 'Yes, sleeping humans', 'Yes, locked vaults'], 'correct': 1, 'explanation': 'Even stationary buildings on Earth are in rapid motion because Earth rotates on its axis and orbits the Sun.', 'study_insight': 'All motion in physics must be described relative to a specific reference origin.'}]}, {'id': 14, 'title': 'Straight Path', 'subtitle': 'Rectilinear Paths, Straight Trajectories & Everyday Examples', 'concept_html': '\n<div class="grid grid-cols-1 md:grid-cols-2 gap-4">\n    <div class="bg-slate-800/80 p-4 rounded-xl border border-cyan-500/30">\n        <h4 class="text-cyan-400 font-bold text-base mb-2">Defining Linear (Rectilinear) Motion</h4>\n        <p class="text-slate-300 text-sm leading-relaxed mb-3">\n            When an object moves along a <strong>straight-line path</strong>, its movement is classified as <strong>linear</strong> (or <strong>rectilinear</strong>) motion.\n        </p>\n        <p class="text-slate-300 text-sm leading-relaxed">\n            In linear motion, the direction of movement does not change. Every point on the moving body travels in identical parallel straight lines.\n        </p>\n    </div>\n    <div class="bg-slate-800/80 p-4 rounded-xl border border-indigo-500/30">\n        <h4 class="text-indigo-400 font-bold text-base mb-2">Real-World Examples of Linear Motion</h4>\n        <ul class="text-xs text-slate-300 space-y-2">\n            <li class="flex items-start gap-2">\n                <span class="text-indigo-400 font-bold">1.</span>\n                <span><strong>Free Fall Under Gravity:</strong> A stone or ripe mango dropped from a tree falls straight down to the ground.</span>\n            </li>\n            <li class="flex items-start gap-2">\n                <span class="text-indigo-400 font-bold">2.</span>\n                <span><strong>March-Past on Parade:</strong> Soldiers marching in strict, unswerving straight lines on Republic Day.</span>\n            </li>\n            <li class="flex items-start gap-2">\n                <span class="text-indigo-400 font-bold">3.</span>\n                <span><strong>100m Sprint:</strong> Athletes sprinting at maximum speed down straight, parallel race lanes.</span>\n            </li>\n            <li class="flex items-start gap-2">\n                <span class="text-indigo-400 font-bold">4.</span>\n                <span><strong>Vehicle on a Highway:</strong> A car driving down a long, straight desert highway.</span>\n            </li>\n        </ul>\n    </div>\n</div>\n', 'lecture_script': 'Now let us explore the different types of motion based on the geometry of the path an object traces. The simplest and most fundamental type is linear motion, also known as rectilinear motion. This occurs whenever an object moves along a straight line without curving or turning. Think about a ripe mango that detaches from a branch: gravity pulls it straight down toward the ground in pure linear motion. When soldiers perform a march-past parade during Republic Day celebrations along Kartavya Path, their synchronized steps proceed in clean, unswerving straight lines. Similarly, sprinters competing in a 100-metre race stay strictly within their parallel straight lanes from start to finish. Whenever the path traced is a straight line, the motion is linear.', 'spoken_text': 'Slide 14: Straight Path. Rectilinear Paths, Straight Trajectories and Everyday Examples. Now let us explore the different types of motion based on the geometry of the path an object traces. The simplest and most fundamental type is linear motion, also known as rectilinear motion. This occurs whenever an object moves along a straight line without curving or turning. Think about a ripe mango that detaches from a branch: gravity pulls it straight down toward the ground in pure linear motion. When soldiers perform a march-past parade during Republic Day celebrations along Kartavya Path, their synchronized steps proceed in clean, unswerving straight lines. Similarly, sprinters competing in a 100-metre race stay strictly within their parallel straight lanes from start to finish. Whenever the path traced is a straight line, the motion is linear.', 'checkpoints': [{'question': 'What type of motion is exhibited by a stone falling freely from a rooftop?', 'options': ['Circular motion', 'Linear (rectilinear) motion', 'Oscillatory motion', 'Random motion'], 'correct': 1, 'explanation': 'A dropped stone travels straight downwards along a vertical line under the pull of gravity.', 'study_insight': 'Straight-line movement is termed linear or rectilinear motion.'}, {'question': 'Which of the following is an example of linear motion?', 'options': ['The spinning blades of a ceiling fan', 'Soldiers marching in a straight parade line', 'A child swinging on a swing', 'The pendulum of a grandfather clock'], 'correct': 1, 'explanation': 'Marching soldiers advance in a straight line, which is classic linear motion.', 'study_insight': 'Circular and swinging motions involve curved or to-and-fro paths.'}]}, {'id': 15, 'title': 'Circle Spin', 'subtitle': 'Fixed Distances, Circular Paths & Spinning Axes', 'concept_html': '\n<div class="grid grid-cols-1 md:grid-cols-2 gap-4">\n    <div class="bg-slate-800/80 p-4 rounded-xl border border-emerald-500/30">\n        <h4 class="text-emerald-400 font-bold text-base mb-2">Defining Circular Motion</h4>\n        <p class="text-slate-300 text-sm leading-relaxed mb-3">\n            When an object moves along a circular trajectory such that its <strong>distance from a central fixed point remains constant</strong>, it executes <strong>circular motion</strong>.\n        </p>\n        <p class="text-slate-300 text-sm leading-relaxed">\n            The radius of the circular path stays fixed throughout the revolution.\n        </p>\n    </div>\n    <div class="bg-slate-800/80 p-4 rounded-xl border border-sky-500/30">\n        <h4 class="text-sky-400 font-bold text-base mb-2">Everyday Circular & Rotational Systems</h4>\n        <ul class="text-xs text-slate-300 space-y-2">\n            <li class="flex items-start gap-2">\n                <span class="text-sky-400 font-bold">•</span>\n                <span><strong>Whirled Stone on a String:</strong> An eraser or pebble tied to a string and whirled overhead in a horizontal circle.</span>\n            </li>\n            <li class="flex items-start gap-2">\n                <span class="text-sky-400 font-bold">•</span>\n                <span><strong>Blades of a Ceiling Fan:</strong> The fan blades rotate around a central motor spindle at fixed radial distance.</span>\n            </li>\n            <li class="flex items-start gap-2">\n                <span class="text-sky-400 font-bold">•</span>\n                <span><strong>Hands of a Clock:</strong> The tip of the second hand traces a circular circumference around the central dial pin.</span>\n            </li>\n            <li class="flex items-start gap-2">\n                <span class="text-sky-400 font-bold">•</span>\n                <span><strong>Carnival Merry-Go-Round:</strong> Wooden horses revolving in circular loops at equal radial distance.</span>\n            </li>\n        </ul>\n    </div>\n</div>\n', 'lecture_script': 'What happens when the path of motion curves into a complete closed circle? That is circular motion! Imagine tying an eraser to one end of a string and whirling it around your head. As the eraser spins, its distance from your hand—which is the length of the string—remains completely constant. The eraser traces a circular path around your hand. Think about the blades of a ceiling fan in your classroom: while the central fan rod stays stationary, every point on the fan blade moves in a circle around the central hub. The same is true for the tip of the second hand on a wall clock, revolving in a continuous 360-degree circle every sixty seconds, or children giggling as they spin on a park merry-go-round. When distance from a central fixed point remains constant while moving in a loop, it is circular motion.', 'spoken_text': 'Slide 15: Circular and Rotational Motion. Fixed Distances, Circular Paths and Spinning Axes. What happens when the path of motion curves into a complete closed circle? That is circular motion! Imagine tying an eraser to one end of a string and whirling it around your head. As the eraser spins, its distance from your hand—which is the length of the string—remains completely constant. The eraser traces a circular path around your hand. Think about the blades of a ceiling fan in your classroom: while the central fan rod stays stationary, every point on the fan blade moves in a circle around the central hub. The same is true for the tip of the second hand on a wall clock, revolving in a continuous 360-degree circle every sixty seconds, or children giggling as they spin on a park merry-go-round. When distance from a central fixed point remains constant while moving in a loop, it is circular motion.', 'checkpoints': [{'question': 'What remains constant when an object moves in uniform circular motion?', 'options': ['Its colour', 'Its distance from the fixed central pivot point', 'The direction it faces', 'Its weight'], 'correct': 1, 'explanation': 'In circular motion, the object maintains a constant radial distance from the central axis.', 'study_insight': 'The radius of the circular path stays fixed.'}, {'question': 'What type of motion is executed by the tip of the hands of a clock?', 'options': ['Linear motion', 'Circular motion', 'Oscillatory motion', 'Random motion'], 'correct': 1, 'explanation': 'The tip of a clock hand sweeps out a circle around the central pivot pin.', 'study_insight': 'It also exhibits periodic motion because it repeats each complete cycle in fixed time.'}]}, {'id': 16, 'title': 'To and Fro', 'subtitle': 'To-and-Fro Vibrations, Swings, Pendulums & Periodic Cycles', 'concept_html': '\n<div class="grid grid-cols-1 md:grid-cols-2 gap-4">\n    <div class="bg-slate-800/80 p-4 rounded-xl border border-purple-500/30">\n        <h4 class="text-purple-400 font-bold text-base mb-2">Oscillatory (To-and-Fro) Motion</h4>\n        <p class="text-slate-300 text-sm leading-relaxed mb-3">\n            When an object moves <strong>to and fro</strong> (back and forth) about a central fixed mean position, its motion is called <strong>oscillatory motion</strong>.\n        </p>\n        <ul class="text-xs text-slate-300 space-y-1.5">\n            <li>• <strong>Swinging Pendulum:</strong> A metal bob swinging symmetrically left and right past its lowest center point.</li>\n            <li>• <strong>Playground Swing:</strong> A child swinging forwards and backwards.</li>\n            <li>• <strong>Vibrating Musical Strings:</strong> Plucking the string of a sitar, guitar, or veena.</li>\n        </ul>\n    </div>\n    <div class="bg-slate-800/80 p-4 rounded-xl border border-amber-500/30">\n        <h4 class="text-amber-400 font-bold text-base mb-2">Periodic Nature of Motion</h4>\n        <p class="text-slate-300 text-sm leading-relaxed mb-3">\n            A motion that <strong>repeats itself after regular, fixed intervals of time</strong> is classified as <strong>periodic motion</strong>.\n        </p>\n        <div class="p-3 bg-amber-950/40 rounded-lg border border-amber-500/20 text-xs text-amber-300">\n            <strong>Key Insight:</strong> Most oscillatory motions (like pendulums) and circular motions (like planetary orbits and clock hands) are <strong>periodic</strong> because they complete each cycle in an exact, predictable duration of time!\n        </div>\n    </div>\n</div>\n', 'lecture_script': 'Finally, let us explore motion that repeats back and forth: oscillatory motion! When a child sits on a playground swing, they do not travel along a straight line, nor do they spin in a full 360-degree loop. Instead, they move forward, slow down, stop, reverse backward past the center, stop again, and swing forward. This to-and-fro movement about a central equilibrium position is called oscillatory motion. You see it in the swinging pendulum of an antique grandfather clock, the bobbing of a spring, the prongs of a struck tuning fork, and the vibrating strings of a sitar or guitar that produce musical notes. Now notice a vital characteristic: the pendulum swings back and forth in regular, repeatable cycles. Any motion that repeats after equal, fixed intervals of time is called periodic motion. Both circular orbits and oscillatory swings are beautiful examples of periodic motion in our cosmos.', 'spoken_text': 'Slide 16: Oscillatory and Periodic Motion. To-and-Fro Vibrations, Swings, Pendulums and Periodic Cycles. Finally, let us explore motion that repeats back and forth: oscillatory motion! When a child sits on a playground swing, they do not travel along a straight line, nor do they spin in a full 360-degree loop. Instead, they move forward, slow down, stop, reverse backward past the center, stop again, and swing forward. This to-and-fro movement about a central equilibrium position is called oscillatory motion. You see it in the swinging pendulum of an antique grandfather clock, the bobbing of a spring, the prongs of a struck tuning fork, and the vibrating strings of a sitar or guitar that produce musical notes. Now notice a vital characteristic: the pendulum swings back and forth in regular, repeatable cycles. Any motion that repeats after equal, fixed intervals of time is called periodic motion. Both circular orbits and oscillatory swings are beautiful examples of periodic motion in our cosmos.', 'checkpoints': [{'question': 'What type of motion is exhibited by a child on a playground swing or a clock pendulum?', 'options': ['Linear motion', 'Circular motion', 'Oscillatory (to-and-fro) motion', 'Random motion'], 'correct': 2, 'explanation': 'A swing moves to and fro about a central resting position, which is oscillatory motion.', 'study_insight': 'Oscillatory motion alternates direction repeatedly across a central point.'}, {'question': 'What is any motion that repeats itself at regular, fixed time intervals called?', 'options': ['Periodic motion', 'Linear motion', 'Curvilinear motion', 'Accelerated motion'], 'correct': 0, 'explanation': "Motion repeating over equal time periods is periodic (e.g., Earth's rotation, swinging pendulum, heartbeat).", 'study_insight': 'Both uniform circular motion and regular oscillatory motion are periodic.'}]}]

QUIZ_QUESTIONS = [{'id': 1, 'slide_id': 17, 'challenge_num': 1, 'q_num': 1, 'question': 'What is the primary reason why handspans, foot lengths, and cubits are not used as standard units?', 'options': ['They are too difficult to remember', 'They vary from person to person depending on body size', 'They cannot be used outdoors', 'They are only used in winter'], 'correct': 1, 'explanation': 'Human body dimensions vary between individuals, making body-part units inconsistent and non-standard.', 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. A handspan depends on the size of an individual's hand, which differs based on age, height, and genetics.</p>\n    <p>2. If two people measure the same classroom desk, they will obtain different numbers of handspans.</p>\n    <p>3. Standard units must remain constant regardless of who performs the measurement.</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: They vary from person to person depending on body size</p>\n</div>\n"}, {'id': 2, 'slide_id': 17, 'challenge_num': 1, 'q_num': 2, 'question': 'What are the two essential components required to express any scientific measurement?', 'options': ['A tool and a colour', 'A number and a unit', 'A speed and a direction', 'A mass and a volume'], 'correct': 1, 'explanation': 'Every measurement consists of a numerical magnitude (number) and a standard reference quantity (unit), such as 15 cm.', 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. Stating only a number (e.g., '12') gives no physical meaning.</p>\n    <p>2. A unit defines the standard reference against which the quantity is compared.</p>\n    <p>3. Thus, a complete measurement requires both: Number x Unit (e.g., 12 metres).</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: A number and a unit</p>\n</div>\n"}, {'id': 3, 'slide_id': 17, 'challenge_num': 1, 'q_num': 3, 'question': 'Which ancient Indus Valley archaeological excavation yielded an ivory measuring scale with 1.7 mm divisions?', 'options': ['Lothal (Gujarat)', 'Sanchi (Madhya Pradesh)', 'Taxila', 'Konark (Odisha)'], 'correct': 0, 'explanation': 'Archaeologists discovered an intricately calibrated ivory scale with ~1.7 mm divisions at Lothal, Gujarat.', 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. Lothal was a major port and dockyard city of the Harappan civilization.</p>\n    <p>2. The ivory scale found there dates to around 2400 BCE.</p>\n    <p>3. Its 1.7 mm subdivisions demonstrate advanced ancient standardization in civic planning.</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: Lothal (Gujarat)</p>\n</div>\n"}, {'id': 4, 'slide_id': 17, 'challenge_num': 1, 'q_num': 4, 'question': 'What ancient Indian unit of length was defined based on the average width of a human finger?', 'options': ['Yojana', 'Dhanusa', 'Angula', 'Hasta'], 'correct': 2, 'explanation': 'Angula was the traditional Indian unit corresponding to finger width, widely used in woodworking and sculpture.', 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. 'Angula' means finger in Sanskrit.</p>\n    <p>2. Four finger widths formed 'char angula'.</p>\n    <p>3. Larger multiples included hasta (cubit, 24 angulas) and dhanusa (bow, 4 hastas).</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: Angula</p>\n</div>\n"}, {'id': 5, 'slide_id': 17, 'challenge_num': 1, 'q_num': 5, 'question': 'What ancient Indian unit was used to measure long intercity travel distances?', 'options': ['Balisht', 'Yojana', 'Angula', 'Pace'], 'correct': 1, 'explanation': 'Yojana was an ancient Indian unit used for astronomical and long terrestrial travel distances, approximately 12 to 15 km.', 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. Ancient texts describe kingdom boundaries and journeys in yojanas.</p>\n    <p>2. One yojana is traditionally regarded as approximately 12 to 15 kilometres.</p>\n    <p>3. Angula and balisht were for small, local handheld objects.</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: Yojana</p>\n</div>\n"}, {'id': 6, 'slide_id': 17, 'challenge_num': 1, 'q_num': 6, 'question': "What does the abbreviation 'SI' in the International System of Units stand for?", 'options': ['Standard India', "Système International d'Unités", 'Scientific Index', 'System of Instruments'], 'correct': 1, 'explanation': "SI stands for 'Système International d'Unités' (French for International System of Units), adopted globally in 1960.", 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. The General Conference on Weights and Measures adopted the unified system in 1960.</p>\n    <p>2. In French, it is titled 'Système International d'Unités'.</p>\n    <p>3. The official international abbreviation in all languages is 'SI'.</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: Système International d'Unités</p>\n</div>\n"}, {'id': 7, 'slide_id': 17, 'challenge_num': 1, 'q_num': 7, 'question': 'What is the standard base SI unit of length?', 'options': ['Kilometre', 'Centimetre', 'Metre', 'Millimetre'], 'correct': 2, 'explanation': 'The metre (symbol: m) is the fundamental base unit of length in the International System of Units.', 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. The SI system has seven base units.</p>\n    <p>2. For the physical quantity of length, the base unit is the metre.</p>\n    <p>3. Centimetres, millimetres, and kilometres are derived prefixes (subunits and multiples).</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: Metre</p>\n</div>\n"}, {'id': 8, 'slide_id': 17, 'challenge_num': 1, 'q_num': 8, 'question': 'Why did nations around the world agree to adopt a single international system of units (SI)?', 'options': ['To eliminate confusion in international commerce, travel, and science', 'Because rulers could only be made in France', 'To make math harder for students', 'Because human hands were banned'], 'correct': 0, 'explanation': 'A unified standard ensures seamless international trade, industrial manufacturing, and scientific communication without conversion errors.', 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. Having different units in every port caused severe commercial fraud and misunderstanding.</p>\n    <p>2. Machine parts manufactured in one country could not fit equipment in another.</p>\n    <p>3. Global standardization solved this by establishing identical units worldwide.</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: To eliminate confusion in international commerce, travel, and science</p>\n</div>\n"}, {'id': 9, 'slide_id': 17, 'challenge_num': 1, 'q_num': 9, 'question': 'What traditional body unit represents the distance from the elbow to the tip of the middle finger?', 'options': ['Handspan (Balisht)', 'Cubit (Hath)', 'Pace (Stride)', 'Fathom'], 'correct': 1, 'explanation': 'A cubit (or hath in Hindi) is the historical measure of length from the elbow joint to the tip of the extended middle finger.', 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. A handspan is from thumb tip to little finger tip.</p>\n    <p>2. A cubit (hath) spans the entire forearm from elbow to middle finger tip.</p>\n    <p>3. It was historically used in cloth markets and garland stalls.</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: Cubit (Hath)</p>\n</div>\n"}, {'id': 10, 'slide_id': 17, 'challenge_num': 1, 'q_num': 10, 'question': 'What is the correct scientific symbol for the SI base unit of length?', 'options': ['M', 'mt', 'm', 'mtr'], 'correct': 2, 'explanation': "The SI symbol for the metre is strictly a lowercase 'm'.", 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. In SI conventions, units named after common objects or non-persons are written in lowercase.</p>\n    <p>2. 'M' denotes the prefix 'mega' (million).</p>\n    <p>3. 'mt' or 'mtr' are non-standard informal abbreviations; 'm' is the only official symbol.</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: m</p>\n</div>\n"}, {'id': 11, 'slide_id': 18, 'challenge_num': 2, 'q_num': 11, 'question': 'How many centimetres are there in 1 metre?', 'options': ['10 cm', '100 cm', '1,000 cm', '0.01 cm'], 'correct': 1, 'explanation': "The prefix 'centi' means one-hundredth (1/100), meaning there are 100 centimetres in 1 metre.", 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. 1 metre is divided into 100 equal parts.</p>\n    <p>2. Each part is called a centimetre (cm).</p>\n    <p>3. Therefore: 1 m = 100 cm.</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: 100 cm</p>\n</div>\n"}, {'id': 12, 'slide_id': 18, 'challenge_num': 2, 'q_num': 12, 'question': 'What is the smallest division typically marked on a standard 15-cm student ruler?', 'options': ['1 centimetre', '1 millimetre', '1 metre', '1 inch'], 'correct': 1, 'explanation': 'A standard school ruler subdivides each centimetre into 10 millimetres, so the smallest marked division is 1 mm (0.1 cm).', 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. On a 15-cm scale, numbers 1, 2, 3... mark centimetres.</p>\n    <p>2. Between each numbered centimetre, there are 10 small sub-divisions.</p>\n    <p>3. Each tiny sub-division represents 1 millimetre (1 mm = 0.1 cm).</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: 1 millimetre</p>\n</div>\n"}, {'id': 13, 'slide_id': 18, 'challenge_num': 2, 'q_num': 13, 'question': 'A runner completes a 5-kilometre race. How many metres did the runner cover?', 'options': ['500 m', '5,000 m', '50,000 m', '500,000 m'], 'correct': 1, 'explanation': 'Since 1 km = 1,000 m, 5 km = 5 x 1,000 = 5,000 metres.', 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. The prefix 'kilo' equals 1,000.</p>\n    <p>2. 1 km = 1,000 m.</p>\n    <p>3. Multiply: 5 km x 1,000 m/km = 5,000 m.</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: 5,000 m</p>\n</div>\n"}, {'id': 14, 'slide_id': 18, 'challenge_num': 2, 'q_num': 14, 'question': 'How many centimetres are equivalent to 1 customary inch?', 'options': ['1.50 cm', '2.54 cm', '3.14 cm', '5.00 cm'], 'correct': 1, 'explanation': 'By international definition, 1 inch is exactly equal to 2.54 centimetres.', 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. The inch is a customary Anglo-American unit of length.</p>\n    <p>2. 1 inch = 2.54 cm.</p>\n    <p>3. 12 inches make 1 foot (approx. 30.48 cm).</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: 2.54 cm</p>\n</div>\n"}, {'id': 15, 'slide_id': 18, 'challenge_num': 2, 'q_num': 15, 'question': 'Which measuring tool should be chosen to measure the chest girth of an athlete?', 'options': ['A 15-cm rigid plastic scale', 'A wooden metre stick', "A flexible tailor's measuring tape", 'A steel surveyor chain'], 'correct': 2, 'explanation': "Human body curves require a flexible tailor's tape that wraps smoothly around contours without gaps.", 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. The human torso has a curved, oval cross-section.</p>\n    <p>2. Rigid scales cannot bend to conform to body curvature.</p>\n    <p>3. A flexible fiberglass tailor's tape wraps cleanly around the chest to provide an accurate girth reading.</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: A flexible tailor's measuring tape</p>\n</div>\n"}, {'id': 16, 'slide_id': 18, 'challenge_num': 2, 'q_num': 16, 'question': 'What is the proper position of the eye when taking a reading on a scale to prevent parallax error?', 'options': ['Looking from the left side at 45 degrees', 'Directly vertically above the mark at 90 degrees (Position B)', 'Looking from the right side at 45 degrees', 'Looking from underneath the table'], 'correct': 1, 'explanation': 'The eye must be vertically aligned directly above the mark being read to eliminate angular parallax distortion.', 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. Rulers have a small physical thickness.</p>\n    <p>2. Viewing from an oblique angle (left or right) shifts the apparent position of the mark relative to the object.</p>\n    <p>3. Aligning the eye vertically at 90 degrees (Position B) ensures zero line-of-sight deviation.</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: Directly vertically above the mark at 90 degrees (Position B)</p>\n</div>\n"}, {'id': 17, 'slide_id': 18, 'challenge_num': 2, 'q_num': 17, 'question': 'What happens if a student reads a scale with their eye positioned too far to the left (Position A)?', 'options': ['The reading is completely accurate', 'The object appears slightly longer than it truly is due to angular parallax', 'The ruler becomes magnetic', 'The numbers change colour'], 'correct': 1, 'explanation': 'Viewing from the left projects an angled line of sight that crosses a higher division on the scale, causing a positive parallax error.', 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. Looking from Position A (left angle) creates an oblique line of sight.</p>\n    <p>2. The object's edge appears aligned with a tick mark further to the right.</p>\n    <p>3. This produces an artificially inflated, inaccurate reading.</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: The object appears slightly longer than it truly is due to angular parallax</p>\n</div>\n"}, {'id': 18, 'slide_id': 18, 'challenge_num': 2, 'q_num': 18, 'question': "A student measures a pencil with a broken ruler, starting at 1.0 cm. The opposite tip reads 8.7 cm. What is the pencil's length?", 'options': ['8.7 cm', '1.0 cm', '7.7 cm', '9.7 cm'], 'correct': 2, 'explanation': 'True Length = Final Reading - Initial Reading = 8.7 cm - 1.0 cm = 7.7 cm.', 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. The initial mark is 1.0 cm (not 0.0 cm).</p>\n    <p>2. The final mark is 8.7 cm.</p>\n    <p>3. Subtract: 8.7 cm - 1.0 cm = 7.7 cm.</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: 7.7 cm</p>\n</div>\n"}, {'id': 19, 'slide_id': 18, 'challenge_num': 2, 'q_num': 19, 'question': 'Why should a student avoid starting a measurement at a chipped, worn-out zero edge of a scale?', 'options': ['The chipped edge makes the pencil break', 'The exact zero point cannot be seen, leading to random errors', 'Zero marks carry electric shock', 'Rulers are only meant to start at 5 cm'], 'correct': 1, 'explanation': 'A worn or broken zero edge obscures the true datum point, introducing systematic measurement error.', 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. Over time, plastic ruler ends get chipped and rounded.</p>\n    <p>2. Estimating where the 0.0 mark used to be leads to inaccurate guesswork.</p>\n    <p>3. Starting at an intact whole mark (like 1.0 cm or 2.0 cm) guarantees precision through subtraction.</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: The exact zero point cannot be seen, leading to random errors</p>\n</div>\n"}, {'id': 20, 'slide_id': 18, 'challenge_num': 2, 'q_num': 20, 'question': "If an object's start aligns with 3.0 cm and its end aligns with 9.4 cm on a scale, what is its true length in millimetres?", 'options': ['64 mm', '94 mm', '30 mm', '6.4 mm'], 'correct': 0, 'explanation': 'Length in cm = 9.4 - 3.0 = 6.4 cm. Converting to mm: 6.4 x 10 = 64 mm.', 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. Length in cm = 9.4 cm - 3.0 cm = 6.4 cm.</p>\n    <p>2. Since 1 cm = 10 mm, multiply by 10.</p>\n    <p>3. 6.4 cm x 10 mm/cm = 64 mm.</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: 64 mm</p>\n</div>\n"}, {'id': 21, 'slide_id': 19, 'challenge_num': 3, 'q_num': 21, 'question': 'Which of the following notations strictly adheres to official SI writing rules?', 'options': ['25ms', '25 cms.', '25 cm', '25CM'], 'correct': 2, 'explanation': "'25 cm' includes a single space between the number and unit, lowercase symbol, no plural 's', and no period.", 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. Rule 1: A space must separate the numeric value from the symbol ('25 cm', not '25cm').</p>\n    <p>2. Rule 2: Symbols never take a plural 's' ('cm', not 'cms').</p>\n    <p>3. Rule 3: Symbols are written in lowercase ('cm', not 'CM').</p>\n    <p>4. Rule 4: No full stop after a unit symbol unless at the end of a sentence.</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: 25 cm</p>\n</div>\n"}, {'id': 22, 'slide_id': 19, 'challenge_num': 3, 'q_num': 22, 'question': "Why is writing '10 ms' for ten metres scientifically misleading?", 'options': ["Because 'ms' stands for milliseconds, a unit of time", "Because 'ms' stands for magnetic speed", 'Because metres cannot be plural', 'Because 10 is too large for metres'], 'correct': 0, 'explanation': "In SI conventions, 'ms' represents milliseconds ($10^{-3}$ seconds), not metres. Metre is always 'm'.", 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. The SI prefix 'm' stands for milli ($10^{-3}$), and 's' stands for seconds.</p>\n    <p>2. Therefore, 'ms' strictly denotes milliseconds.</p>\n    <p>3. Adding an 's' to make 'm' plural alters the physical dimension from length to time!</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: Because 'ms' stands for milliseconds, a unit of time</p>\n</div>\n"}, {'id': 23, 'slide_id': 19, 'challenge_num': 3, 'q_num': 23, 'question': 'How are tactile scales designed to assist visually challenged learners?', 'options': ['They speak aloud through a microphone', 'They feature raised, embossed dots and notched edges that can be felt by fingertips', 'They glow in the dark', 'They are made of heavy iron'], 'correct': 1, 'explanation': 'Tactile rulers have embossed markings and Braille ridges enabling visually impaired students to measure length by touch.', 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. Standard rulers rely on printed visual lines.</p>\n    <p>2. Tactile scales emboss these lines into physical ridges and dots.</p>\n    <p>3. Students run their fingertips along the edge to identify centimetre and millimetre marks independently.</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: They feature raised, embossed dots and notched edges that can be felt by fingertips</p>\n</div>\n"}, {'id': 24, 'slide_id': 19, 'challenge_num': 3, 'q_num': 24, 'question': 'What is the recommended method to measure the length of a curved line drawn on paper?', 'options': ['Break the scale into tiny pieces', 'Lay a flexible thread along the curve, mark the ends, and measure the straightened thread on a ruler', 'Estimate by counting squares by eye', 'Soak the paper in water'], 'correct': 1, 'explanation': 'A thread traces the exact curved path; when pulled straight against a scale, it yields the accurate length.', 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. A flexible thread is gently aligned with every bend and curvature of the line.</p>\n    <p>2. The starting and ending points are marked on the thread with ink.</p>\n    <p>3. The thread is then stretched straight along a standard centimetre ruler to read the distance.</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: Lay a flexible thread along the curve, mark the ends, and measure the straightened thread on a ruler</p>\n</div>\n"}, {'id': 25, 'slide_id': 19, 'challenge_num': 3, 'q_num': 25, 'question': 'What is a reference point in physics?', 'options': ['A point that moves as fast as possible', 'A fixed object or location used to specify the position and distance of another object', 'The highest point on a mountain', 'A point where friction is zero'], 'correct': 1, 'explanation': 'A reference point (origin) is a stationary benchmark against which positions, displacements, and motions are measured.', 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. You cannot describe location without saying 'where from'.</p>\n    <p>2. The 'where from' landmark is called the reference point.</p>\n    <p>3. All measurements of distance, direction, and speed depend on the chosen reference frame.</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: A fixed object or location used to specify the position and distance of another object</p>\n</div>\n"}, {'id': 26, 'slide_id': 19, 'challenge_num': 3, 'q_num': 26, 'question': "Anish says: 'My home is 500 metres north of the post office.' What is the reference point in his statement?", 'options': ["Anish's home", 'The post office', 'The school', 'The northern horizon'], 'correct': 1, 'explanation': 'The post office is the stationary origin from which the 500 m northward position is defined.', 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. The position of Anish's home is being described.</p>\n    <p>2. It is specified relative to the post office ('north of the post office').</p>\n    <p>3. Therefore, the post office serves as the reference point.</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: The post office</p>\n</div>\n"}, {'id': 27, 'slide_id': 19, 'challenge_num': 3, 'q_num': 27, 'question': 'When is an object scientifically said to be at rest?', 'options': ['When it stops breathing', 'When its position does not change with respect to a reference point over time', 'When its speed exceeds 100 km/h', 'When it is submerged in water'], 'correct': 1, 'explanation': 'An object is at rest if its spatial coordinates remain unchanged relative to a chosen reference frame as time progresses.', 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. Rest is the absence of position change over time.</p>\n    <p>2. A desk in a classroom does not change its position relative to the floor or walls.</p>\n    <p>3. Hence, it is in a state of rest relative to the classroom.</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: When its position does not change with respect to a reference point over time</p>\n</div>\n"}, {'id': 28, 'slide_id': 19, 'challenge_num': 3, 'q_num': 28, 'question': 'When is an object scientifically defined as being in motion?', 'options': ['When its position changes with respect to a reference point as time passes', 'When it is exposed to sunlight', 'When its mass increases', 'When it becomes magnetic'], 'correct': 0, 'explanation': 'Motion is strictly defined as a continuous change in position over time relative to a chosen reference point.', 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. If position changes from point A to point B as clock seconds advance, movement has occurred.</p>\n    <p>2. This spatial displacement relative to an origin defines motion.</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: When its position changes with respect to a reference point as time passes</p>\n</div>\n"}, {'id': 29, 'slide_id': 19, 'challenge_num': 3, 'q_num': 29, 'question': 'Two friends sit in adjacent seats on a moving bus. Are they in motion or at rest relative to each other?', 'options': ['In rapid motion', 'At rest, because their distance and direction from each other do not change', 'They disappear', 'They are in circular motion'], 'correct': 1, 'explanation': 'Because the relative position between the two passengers is constant over time, they are at rest with respect to each other.', 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. Both passengers travel at the identical velocity of the bus.</p>\n    <p>2. The distance and angle between them remain perfectly fixed.</p>\n    <p>3. Relative to each other's frame of reference, they are completely at rest.</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: At rest, because their distance and direction from each other do not change</p>\n</div>\n"}, {'id': 30, 'slide_id': 19, 'challenge_num': 3, 'q_num': 30, 'question': 'Relative to a bystander standing on the roadside footpath, what is the state of a passenger inside a passing bus?', 'options': ['At rest', 'In motion, traveling with the speed of the bus', 'Suspended in space', 'Moving backwards'], 'correct': 1, 'explanation': "Relative to the fixed road, the passenger's position is changing continuously at the bus's cruising speed, so they are in motion.", 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. The roadside bystander serves as the reference point.</p>\n    <p>2. Every second, the distance between the bystander and the passenger changes.</p>\n    <p>3. Therefore, relative to the bystander, the passenger is in motion.</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: In motion, traveling with the speed of the bus</p>\n</div>\n"}, {'id': 31, 'slide_id': 20, 'challenge_num': 4, 'q_num': 31, 'question': 'What type of motion is executed by an apple falling straight down from a tree branch?', 'options': ['Circular motion', 'Linear (rectilinear) motion', 'Oscillatory motion', 'Periodic rotational motion'], 'correct': 1, 'explanation': 'An apple falling under gravity moves along a straight vertical line, which is linear (rectilinear) motion.', 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. Gravity pulls free-falling objects directly toward the center of the Earth.</p>\n    <p>2. The path traced is a straight vertical line.</p>\n    <p>3. Straight-line motion is classified as linear (or rectilinear) motion.</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: Linear (rectilinear) motion</p>\n</div>\n"}, {'id': 32, 'slide_id': 20, 'challenge_num': 4, 'q_num': 32, 'question': 'Which of the following is an everyday example of linear (rectilinear) motion?', 'options': ['A child spinning on a merry-go-round', 'Soldiers marching on a straight parade ground', 'The swinging pendulum of a wall clock', 'A stone whirled in a circle on a string'], 'correct': 1, 'explanation': 'Marching soldiers advance in strict, straight parallel paths without turning, exemplifying rectilinear motion.', 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. A merry-go-round and whirled stone follow curved circular paths.</p>\n    <p>2. A clock pendulum moves to-and-fro in oscillatory motion.</p>\n    <p>3. Soldiers marching along a straight track move in linear motion.</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: Soldiers marching on a straight parade ground</p>\n</div>\n"}, {'id': 33, 'slide_id': 20, 'challenge_num': 4, 'q_num': 33, 'question': 'What type of motion is performed by a stone tied to a string and whirled overhead?', 'options': ['Linear motion', 'Circular motion', 'Oscillatory motion', 'Non-periodic motion'], 'correct': 1, 'explanation': 'The stone traces a circular path around the hand while maintaining a constant radial distance equal to string length.', 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. The string keeps the stone at a fixed distance from the center.</p>\n    <p>2. The stone travels along the circumference of a circle.</p>\n    <p>3. Movement along a circular path at constant radial distance is circular motion.</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: Circular motion</p>\n</div>\n"}, {'id': 34, 'slide_id': 20, 'challenge_num': 4, 'q_num': 34, 'question': 'Which component of a ceiling fan executes circular motion when the fan is switched on?', 'options': ['The stationary ceiling mounting hook', 'Points on the rotating blades', 'The electrical switch on the wall', 'The room floor'], 'correct': 1, 'explanation': 'Every point on the fan blade moves in a circular path centered around the motor spindle.', 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. The motor spindle acts as the fixed center of rotation.</p>\n    <p>2. Any spot marked on a blade travels around that center at a constant radius.</p>\n    <p>3. Hence, the blades execute circular motion.</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: Points on the rotating blades</p>\n</div>\n"}, {'id': 35, 'slide_id': 20, 'challenge_num': 4, 'q_num': 35, 'question': 'What type of motion is demonstrated by a swinging pendulum or a child on a playground swing?', 'options': ['Linear motion', 'Circular motion', 'Oscillatory (to-and-fro) motion', 'Random motion'], 'correct': 2, 'explanation': 'Back-and-forth movement about a central equilibrium mean position is defined as oscillatory motion.', 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. The swing or pendulum bob starts at the lowest central point (mean position).</p>\n    <p>2. It swings forward to an extreme, stops, reverses through the center to the opposite extreme, and repeats.</p>\n    <p>3. This to-and-fro movement across a central rest point is oscillatory motion.</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: Oscillatory (to-and-fro) motion</p>\n</div>\n"}, {'id': 36, 'slide_id': 20, 'challenge_num': 4, 'q_num': 36, 'question': 'When the string of a sitar or guitar is plucked, what kind of motion does it perform to produce sound?', 'options': ['Linear motion across the room', 'Oscillatory (vibrational) motion', 'Circular motion around the neck', 'Uniform translational motion'], 'correct': 1, 'explanation': 'A plucked musical string vibrates rapidly to-and-fro across its resting position, which is oscillatory (vibratory) motion.', 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. Plucking pulls the string away from its straight equilibrium line.</p>\n    <p>2. Elastic tension pulls it back, causing it to overshoot and oscillate back and forth.</p>\n    <p>3. These rapid oscillatory vibrations create acoustic sound waves in the air.</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: Oscillatory (vibrational) motion</p>\n</div>\n"}, {'id': 37, 'slide_id': 20, 'challenge_num': 4, 'q_num': 37, 'question': 'What is the defining characteristic of periodic motion?', 'options': ['It only moves in straight lines', 'It repeats its path after regular, fixed intervals of time', 'It stops permanently after 10 seconds', 'It creates light'], 'correct': 1, 'explanation': 'Periodic motion is any motion that repeats itself in identical cycles over equal, regular intervals of time.', 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. The period is the time taken to complete one full cycle.</p>\n    <p>2. If every cycle takes the exact same duration (e.g., 60 seconds for a clock minute hand, 24 hours for Earth rotation), it is periodic.</p>\n    <p>3. Both uniform circular and regular oscillatory motions are periodic.</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: It repeats its path after regular, fixed intervals of time</p>\n</div>\n"}, {'id': 38, 'slide_id': 20, 'challenge_num': 4, 'q_num': 38, 'question': 'Which of the following motions is both circular AND periodic?', 'options': ['A car slamming on emergency brakes', 'The revolution of the tip of the second-hand on a clock', 'A falling raindrop', 'A football kicked across a field'], 'correct': 1, 'explanation': 'The second-hand moves in a circle (circular) and completes each 360-degree revolution in exactly 60 seconds (periodic).', 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. The tip follows a circular path at constant radius (circular motion).</p>\n    <p>2. It repeats its cycle every 60 seconds predictably (periodic motion).</p>\n    <p>3. Therefore, it exhibits both circular and periodic motion simultaneously.</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: The revolution of the tip of the second-hand on a clock</p>\n</div>\n"}, {'id': 39, 'slide_id': 20, 'challenge_num': 4, 'q_num': 39, 'question': 'A drill machine bit rotates rapidly to drill a hole into a wooden plank while simultaneously moving forward into the wood. What combined motions does it exhibit?', 'options': ['Only linear motion', 'Only circular motion', 'Combined rotational (circular) and linear motion', 'Oscillatory and random motion'], 'correct': 2, 'explanation': 'The drill bit spins around its axis (rotational/circular) while advancing forward in a straight line (linear).', 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. Spinning around its central axis represents rotational motion.</p>\n    <p>2. Penetrating straight forward into the plank represents linear motion.</p>\n    <p>3. Real-world machinery frequently combines multiple types of motion.</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: Combined rotational (circular) and linear motion</p>\n</div>\n"}, {'id': 40, 'slide_id': 20, 'challenge_num': 4, 'q_num': 40, 'question': 'Which of the following correctly pairs an object with its primary type of motion?', 'options': ['Marching soldier — Circular motion', 'Struck tuning fork — Oscillatory motion', 'Falling coconut — Oscillatory motion', 'Clock pendulum — Linear motion'], 'correct': 1, 'explanation': 'The prongs of a struck tuning fork oscillate to-and-fro rapidly, generating sound vibrations.', 'solution_html': "\n<div class='text-sm space-y-2'>\n    <p><strong>Step-by-Step Explanation:</strong></p>\n    <p>1. Marching soldiers execute linear motion.</p>\n    <p>2. A falling coconut executes linear (free-fall) motion.</p>\n    <p>3. A clock pendulum executes oscillatory motion.</p>\n    <p>4. A struck tuning fork executes oscillatory (vibrational) motion.</p>\n    <p class='text-emerald-400 font-bold'>Correct Option: Struck tuning fork — Oscillatory motion</p>\n</div>\n"}]
